              </div>
              <p className="text-[11px] text-slate-400 mt-1">
                {isKhmer ? 'យ៉ាងតិច ៨ តួអក្សរ' : 'Minimum 8 characters'}
              </p>
            </div>

            {/* Confirm Password */}
            <div>
              <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                {isKhmer ? 'បញ្ជាក់ពាក្យសម្ងាត់ថ្មី' : 'Confirm New Password'} <span className="text-red-500">*</span>
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none text-slate-400">
                  <FiLock size={16} />
                </div>
                <input
                  type={showConfirmPassword ? 'text' : 'password'}
                  value={passwordData.confirm_password}
                  onChange={(e) => setPasswordData({ ...passwordData, confirm_password: e.target.value })}
                  required
                  placeholder="••••••••"
                  className="w-full pl-10 pr-11 py-2.5 rounded-xl border border-slate-200 text-sm text-slate-900 focus:border-[#2563EB] focus:ring-2 focus:ring-blue-100 outline-none transition"
                />
                <button
                  type="button"
                  onClick={() => setShowConfirmPassword((prev) => !prev)}
                  className="absolute inset-y-0 right-0 pr-3.5 flex items-center text-slate-400 hover:text-slate-600"
                >
                  {showConfirmPassword ? <FiEyeOff size={16} /> : <FiEye size={16} />}
                </button>
              </div>
            </div>

            <div className="pt-4 border-t border-slate-100 flex justify-end">
              <button
                type="submit"
                disabled={passwordLoading}
                className="h-11 px-6 bg-[#2563EB] hover:bg-[#1D4ED8] disabled:opacity-60 text-white rounded-xl text-xs font-bold inline-flex items-center gap-2 transition-all shadow-sm active:scale-95"
              >
                {passwordLoading ? (
                  <div className="w-4 h-4 rounded-full border-2 border-white border-t-transparent animate-spin" />
                ) : (
                  <FiSave size={16} />
                )}
                <span>{isKhmer ? 'ប្ដូរពាក្យសម្ងាត់ឥឡូវនេះ' : 'Update Password'}</span>
              </button>
            </div>
          </form>
        </AdminCard>
      )}

      {/* TAB 3: SECURITY & DETAILS */}
      {activeTab === 'security' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <AdminCard>
            <h3 className="text-base font-bold text-slate-900 mb-4 flex items-center gap-2">
              <FiShield className="text-[#2563EB]" />
              <span>{isKhmer ? 'សិទ្ធិ & ការអនុញ្ញាត (Privileges)' : 'Security Privileges'}</span>
            </h3>

            <div className="space-y-3.5">
              <div className="flex items-center justify-between p-3.5 rounded-xl bg-slate-50 border border-slate-100">
                <span className="text-xs font-bold text-slate-700">{isKhmer ? 'គ្រប់គ្រងវគ្គសិក្សា (Courses)' : 'Manage Courses'}</span>
                <span className="px-2.5 py-1 rounded-md text-[10px] font-extrabold bg-emerald-100 text-emerald-800 uppercase">Granted</span>
              </div>
              <div className="flex items-center justify-between p-3.5 rounded-xl bg-slate-50 border border-slate-100">
                <span className="text-xs font-bold text-slate-700">{isKhmer ? 'គ្រប់គ្រងវិចិត្រសាល (Gallery & Videos)' : 'Manage Media'}</span>
                <span className="px-2.5 py-1 rounded-md text-[10px] font-extrabold bg-emerald-100 text-emerald-800 uppercase">Granted</span>
              </div>
              <div className="flex items-center justify-between p-3.5 rounded-xl bg-slate-50 border border-slate-100">
                <span className="text-xs font-bold text-slate-700">{isKhmer ? 'គ្រប់គ្រងការកំណត់ (Settings & Brand)' : 'Manage Settings'}</span>
                <span className="px-2.5 py-1 rounded-md text-[10px] font-extrabold bg-emerald-100 text-emerald-800 uppercase">Granted</span>
              </div>
              <div className="flex items-center justify-between p-3.5 rounded-xl bg-slate-50 border border-slate-100">
                <span className="text-xs font-bold text-slate-700">{isKhmer ? 'គ្រប់គ្រងសារទំនាក់ទំនង (Messages)' : 'View Messages'}</span>
                <span className="px-2.5 py-1 rounded-md text-[10px] font-extrabold bg-emerald-100 text-emerald-800 uppercase">Granted</span>
              </div>
            </div>
          </AdminCard>

          <AdminCard>
            <h3 className="text-base font-bold text-slate-900 mb-4 flex items-center gap-2">
              <FiActivity className="text-[#2563EB]" />
              <span>{isKhmer ? 'ព័ត៌មានលម្អិតនៃគណនី' : 'Account Details'}</span>
            </h3>

            <div className="space-y-3.5 text-xs">
              <div className="flex justify-between py-2 border-b border-slate-100">
                <span className="text-slate-500">{isKhmer ? 'អត្តសញ្ញាណគណនី (ID)' : 'Account ID'}</span>
                <span className="font-mono font-bold text-slate-800">#ADM-{profileData.username}</span>
              </div>
              <div className="flex justify-between py-2 border-b border-slate-100">
                <span className="text-slate-500">{isKhmer ? 'កាលបរិច្ឆេទបង្កើត' : 'Account Created'}</span>
                <span className="font-medium text-slate-800">
                  {profileData.created_at ? new Date(profileData.created_at).toLocaleString() : 'System Default'}
                </span>
              </div>
              <div className="flex justify-between py-2 border-b border-slate-100">
                <span className="text-slate-500">{isKhmer ? 'កែប្រែចុងក្រោយ' : 'Last Updated'}</span>
                <span className="font-medium text-slate-800">
                  {profileData.updated_at ? new Date(profileData.updated_at).toLocaleString() : 'Just now'}
                </span>
              </div>
              <div className="flex justify-between py-2">
                <span className="text-slate-500">{isKhmer ? 'ស្ថានភាព Session' : 'Current Session'}</span>
                <span className="font-bold text-emerald-600 flex items-center gap-1.5">
                  <span className="w-2 h-2 rounded-full bg-emerald-500 animate-ping" />
                  <span>Authenticated & Active</span>
                </span>
              </div>
            </div>
          </AdminCard>
        </div>
      )}
    </div>
  );
};

export default AdminProfile;
